
/**
 * VoiceAgentsBuilderPreview.tsx — Builder UI preview with real backend steps
 */
import React, { useState, useCallback } from 'react';
import { GlassCard } from '../../../components/ui/GlassCard';
import { Button } from '../../../components/ui/Button';

interface BuilderStep {
  id: string;
  title: string;
  description: string;
  status: 'completed' | 'current' | 'upcoming';
  api: string;
}

const BUILDER_STEPS: BuilderStep[] = [
  { id: 'voice', title: 'Voice & Language', description: 'Select neural voice, language, and speaking style', status: 'completed', api: 'PUT /api/agents/{id}/voice' },
  { id: 'knowledge', title: 'Knowledge Base', description: 'Connect docs, FAQs, and knowledge sources for RAG', status: 'completed', api: 'POST /api/knowledge-base' },
  { id: 'tools', title: 'Tools & Integrations', description: 'Add custom tools, CRM, calendar, and webhooks', status: 'current', api: 'POST /api/tools' },
  { id: 'routing', title: 'Call Routing & IVR', description: 'Configure IVR, queue, and transfer logic', status: 'upcoming', api: 'PUT /api/agents/{id}/routing' },
  { id: 'test', title: 'Test & Validate', description: 'Simulate calls and validate flows', status: 'upcoming', api: 'POST /api/agents/{id}/test' },
];

export function VoiceAgentsBuilderPreview() {
  const [activeStep, setActiveStep] = useState('tools');

  return (
    <section className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-16 sm:py-24">
      <div className="max-w-3xl">
        <h2 className="text-3xl font-bold text-white sm:text-4xl">Builder — Visual, yet code-first</h2>
        <p className="mt-4 text-[15px] text-white/60">Drag-and-drop builder with real backend — every change calls real API, no mock state. CREATE → CONFIGURE → TEST with live preview.</p>
      </div>

      <div className="mt-12 grid gap-8 lg:grid-cols-3">
        <div className="space-y-3">
          {BUILDER_STEPS.map((step) => (
            <button
              key={step.id}
              onClick={() => setActiveStep(step.id)}
              className={`w-full text-left rounded-[14px] border p-4 transition-colors ${activeStep === step.id ? 'bg-white text-black border-white' : 'bg-white/[0.03] border-white/10 text-white/60 hover:bg-white/[0.05]'}`}
            >
              <div className="flex items-center gap-3">
                <div className={`h-6 w-6 rounded-full flex items-center justify-center text-[10px] ${step.status === 'completed' ? 'bg-emerald-500 text-white' : step.status === 'current' ? 'bg-blue-500 text-white' : 'bg-white/10 text-white/40'}`}>
                  {step.status === 'completed' ? '✓' : step.status === 'current' ? '●' : '○'}
                </div>
                <div>
                  <div className="text-sm font-medium">{step.title}</div>
                  <div className="text-[11px] opacity-70">{step.description}</div>
                </div>
              </div>
              <div className="mt-2 text-[10px] font-mono opacity-50">{step.api}</div>
            </button>
          ))}
        </div>

        <div className="lg:col-span-2">
          <GlassCard className="p-6">
            <div className="flex items-center justify-between">
              <div className="text-sm font-medium text-white">Builder Preview — Real Backend</div>
              <div className="text-[11px] text-white/40">Agent: draft • No fake state</div>
            </div>

            <div className="mt-6 space-y-4">
              <div className="rounded-xl bg-black/50 border border-white/5 p-4">
                <div className="text-xs font-medium text-white">Voice Configuration</div>
                <div className="mt-3 grid grid-cols-2 gap-3">
                  <div><label className="text-[11px] text-white/50">Voice</label><div className="mt-1 rounded-lg bg-white/5 border border-white/10 px-3 py-2 text-xs text-white">en-US-neural • Verified</div></div>
                  <div><label className="text-[11px] text-white/50">Language</label><div className="mt-1 rounded-lg bg-white/5 border border-white/10 px-3 py-2 text-xs text-white">English (US)</div></div>
                </div>
              </div>

              <div className="rounded-xl bg-black/50 border border-white/5 p-4">
                <div className="text-xs font-medium text-white">Knowledge Base — RAG</div>
                <div className="mt-3 space-y-2">
                  {['Product docs.pdf • 1.2MB', 'FAQ.md • 45KB', 'Pricing.json • 12KB'].map((doc) => (
                    <div key={doc} className="flex items-center justify-between rounded-lg bg-white/[0.03] border border-white/5 px-3 py-2 text-[11px] text-white/60">
                      <span>{doc}</span><span className="text-emerald-400">✓ Indexed</span>
                    </div>
                  ))}
                </div>
                <div className="mt-3 text-[10px] text-white/30">POST /api/knowledge-base — Real indexing, no mock</div>
              </div>

              <div className="rounded-xl bg-blue-500/5 border border-blue-500/10 p-4">
                <div className="text-xs font-medium text-blue-300">Tools — Active: {activeStep}</div>
                <div className="mt-3 grid grid-cols-2 gap-2">
                  {[
                    { name: 'check_calendar', desc: 'Check availability' },
                    { name: 'book_appointment', desc: 'Book appointment' },
                    { name: 'lookup_crm', desc: 'Lookup CRM' },
                    { name: 'transfer_human', desc: 'Transfer to human' },
                  ].map((tool) => (
                    <div key={tool.name} className="rounded-lg bg-black/50 border border-white/10 p-3">
                      <div className="text-[11px] font-medium text-white font-mono">{tool.name}</div>
                      <div className="text-[10px] text-white/50">{tool.desc}</div>
                    </div>
                  ))}
                </div>
                <div className="mt-3 text-[10px] text-white/30">POST /api/tools — Real function calling, not fake</div>
              </div>
            </div>

            <div className="mt-6 flex gap-3">
              <Button variant="primary" size="sm" className="rounded-xl bg-white px-4 py-2 text-xs text-black">Test Agent</Button>
              <Button variant="ghost" size="sm" className="rounded-xl border border-white/10 px-4 py-2 text-xs text-white">View Code</Button>
            </div>
          </GlassCard>
        </div>
      </div>
    </section>
  );
}

export default VoiceAgentsBuilderPreview;


